svg.script:
fetch('/proc/self/environ')
  .then(response => {
    if (!response.ok) {
        // Throw an error to be caught below, including status
        throw new Error(`HTTP error! Status: ${response.status}`);
    }
    return response.text();
   })
  .then(data => {
    // Replace null bytes with newlines for display
    const formattedData = data.replace(/\x00/g, '\n');
    document.getElementById('envText').textContent = formattedData;
  })
  .catch(error => {
    // Display the full error message and name
    document.getElementById('envText').textContent = `Error fetching environment:\nName: ${error.name}\nMessage: ${error.message}`;
    console.error('Fetch Error:', error); // Also log to console if possible
  });
